  ]$$::jsonb) as item(
    title text,
    author text,
    publisher text,
    min_players integer,
    max_players integer,
    play_time_minutes integer,
    min_age integer,
    complexity numeric,
    category text,
    description text,
    ownership_status text,
    cover_url text
  )
),
target_library as (
  select id as library_id
  from library.libraries
  where slug = 'jenkins'
)
update library.books books
set
  title = seed.title,
  author = seed.author,
  genre = seed.category,
  description = seed.description,
  cover_url = seed.cover_url,
  ownership_status = seed.ownership_status,
  media_type = 'board_game',
  publisher = seed.publisher,
  min_players = seed.min_players,
  max_players = seed.max_players,
  play_time_minutes = seed.play_time_minutes,
  min_age = seed.min_age,
  complexity = seed.complexity,
  category = seed.category,
  updated_at = now()
from seed, target_library
where books.library_id = target_library.library_id
  and books.media_type = 'board_game'
  and books.deleted_at is null
  and (
    lower(books.title) = lower(seed.title)
    or (books.title = 'Settlers of Catan' and seed.title = 'Catan')
    or (books.title = 'Chess' and seed.title = 'Chess - Magnetic')
  );

