    {"title":"Azul","author":"Michael Kiesling","publisher":"Plan B Games","min_players":2,"max_players":4,"play_time_minutes":45,"min_age":8,"complexity":1.8,"category":"Abstract Strategy","description":"Tile-drafting pattern-building game inspired by Portuguese azulejo tiles.","ownership_status":"wishlist","cover_url":"https://cdn.shoplightspeed.com/shops/636231/files/68363129/1652x1652x2/plan-b-games-azul.jpg"},
