  ]$$::jsonb) as item(
    title text,
    author text,
    publisher text,
    min_players integer,
    max_players integer,
    play_time_minutes integer,
    min_age integer,
    complexity numeric,
    category text,
    description text,
    ownership_status text,
    cover_url text
  )
),
target_library as (
  select id as library_id
  from library.libraries
  where slug = 'jenkins'
)
insert into library.books (
  library_id,
  title,
  author,
  genre,
  description,
  cover_url,
  ownership_status,
  media_type,
  publisher,
  min_players,
  max_players,
  play_time_minutes,
  min_age,
  complexity,
  category
)
select
  target_library.library_id,
  seed.title,
  seed.author,
  seed.category,
  seed.description,
  seed.cover_url,
  seed.ownership_status,
  'board_game',
  seed.publisher,
  seed.min_players,
  seed.max_players,
  seed.play_time_minutes,
  seed.min_age,
  seed.complexity,
  seed.category
from seed, target_library
where not exists (
  select 1
  from library.books existing
  where existing.library_id = target_library.library_id
    and existing.media_type = 'board_game'
    and existing.deleted_at is null
    and lower(existing.title) = lower(seed.title)
);
